#include "../src/game/later_stage_emitters.hpp"
int main(int argc,char**argv){if(argc!=2)return 1;shin::AssetStore assets(argv[1]);shin::IndexedSurface target(640,480);shin::LaterStageEmitters e;e.add(100,100);int count=0;e.spawn=[&](unsigned c,unsigned u,unsigned d,int k,int x,int y){if(c!=0x44e2c0||u!=0x44e3b0||d!=0x44e4f0||k!=0x62||x!=100||y!=100)throw std::runtime_error("spawn fields");++count;};for(int i=0;i<64;++i)e.tick(0,0,assets,target);if(count)return 2;e.tick(0,0,assets,target);if(count!=1)return 3;for(int i=0;i<66;++i)e.tick(0,0,assets,target);return count==2?0:4;}
